const q = $input.item.json.query || {};
const action = q.action || '';
const post_id = q.post_id || '';
return [{ json: { action, post_id } }];

const article = $('Write Article').item.json.text || '';
const kw_data = $('Pick Keyword').item.json;
const dest = kw_data.dest;
const destEn = kw_data.en;
const requested = kw_data.requested_country || dest;

const forbidden = ['جورجيا','Georgia','الأردن','Jordan','تركيا','Turkey','مصر','Egypt',
  'الإمارات','UAE','السعودية','Saudi','لبنان','Lebanon','المغرب','Morocco',
  'إيطاليا','Italy','فرنسا','France','إسبانيا','Spain','ألمانيا','Germany'];

const titleMatch = article.match(/<h1[^>]*>(.*?)<\/h1>/i);
const title = titleMatch ? titleMatch[1].replace(/<[^>]+>/g,'').trim() : '';

const hasForbidden = forbidden.some(f => title.includes(f) || article.slice(0,500).includes(f));
const hasDestination = article.includes(dest) || article.includes(destEn);

if (hasForbidden || !hasDestination) {
  throw new Error(`❌ Gemini كتب عن دولة خاطئة! العنوان: ${title} | المطلوب: ${dest}`);
}

const wrongCountries = ['كازاخستان','Kazakhstan','روسيا','Russia','بولندا','Poland','أوزبكستان','Uzbekistan','الصين','China']
  .filter(c => c !== dest && c !== destEn && (title.includes(c) || article.slice(0,800).includes(c)));

if (wrongCountries.length > 0 && requested) {
  throw new Error(`❌ المقال يذكر ${wrongCountries[0]} بينما المطلوب ${requested} — راجع Pick Keyword / المدخلات`);
}

return [{ json: { ...$input.item.json, validated_country: dest, requested_country: requested } }];

const images = $input.item.json.images || [];
const prepData = $('Prepare Post').item.json;
if (!images.length) {
  return [{ json: { ...prepData, pexelsUrl: '', featuredMediaId: 0 }}];
}
const imageUrl = images[0].url;
return [{ json: { ...prepData, pexelsUrl: imageUrl, imageAlt: prepData.keyword || 'Arcadia Travel' }}];

const prepData = $('Extract Fal.ai URL').item.json;
const mediaId = $input.item.json.id || 0;
return [{ json: { ...prepData, featuredMediaId: mediaId } }];

const prep = $('Prepare Post').item.json;
const fal = $input.item.json;
return [{ json: {
  ...prep,
  featuredMediaId: fal.featuredMediaId || 0,
  imageAlt: fal.imageAlt || prep.keyword,
  fal_image_url: fal.image_url || null
}}];

const posts = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(p => p && p.id);
const prep = $('Prepare Post').item.json;
const slug = prep.slug;
if (posts.length) {
  const p = posts[0];
  throw new Error(`❌ slug "${slug}" موجود مسبقاً (post #${p.id}, status=${p.status}) — لن يُنشأ نسخة -2. حدّث المقال الأصلي أو اختر keyword جديد.`);
}
return [{ json: prep }];
